import{_ as a,o as e,c as o,a5 as n}from"./chunks/framework.C1a7WKBV.js";const u=JSON.parse('{"title":"大模型缓存是什么","description":"上下文缓存（Prompt Cache）的工作原理——为什么它能让你和 AI 的对话更快、更便宜，以及怎么用才命中。","frontmatter":{"title":"大模型缓存是什么","description":"上下文缓存（Prompt Cache）的工作原理——为什么它能让你和 AI 的对话更快、更便宜，以及怎么用才命中。"},"headers":[],"relativePath":"concepts/llm-cache.md","filePath":"concepts/llm-cache.md","lastUpdated":1788838685000}'),s={name:"concepts/llm-cache.md"};function r(l,t,i,d,p,h){return e(),o("div",null,[...t[0]||(t[0]=[n(`<h1 id="大模型缓存是什么" tabindex="-1">大模型缓存是什么 <a class="header-anchor" href="#大模型缓存是什么" aria-label="Permalink to &quot;大模型缓存是什么&quot;">​</a></h1><p>用 Claude Code、Cursor 这类工具时，你可能在用量明细里见过&quot;缓存读取&quot;&quot;Cache Read&quot;这样的字样，费用还特别低。这一篇讲清楚：这个缓存到底是什么、为什么它能省钱提速、以及什么样的对话才能命中它。</p><h2 id="_1-先理解一个问题-模型很-健忘" tabindex="-1">1. 先理解一个问题：模型很&quot;健忘&quot; <a class="header-anchor" href="#_1-先理解一个问题-模型很-健忘" aria-label="Permalink to &quot;1. 先理解一个问题：模型很&quot;健忘&quot;&quot;">​</a></h2><p>大模型本身是<strong>无状态</strong>的——它不记得你们之前聊过什么。</p><p>你在客户端里看到的&quot;连续对话&quot;，实际是这样运作的：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>第 1 轮请求：[系统提示词] + [你的问题 1]</span></span>
<span class="line"><span>第 2 轮请求：[系统提示词] + [问题 1] + [回答 1] + [你的问题 2]</span></span>
<span class="line"><span>第 3 轮请求：[系统提示词] + [问题 1] + [回答 1] + [问题 2] + [回答 2] + [问题 3]</span></span>
<span class="line"><span>……</span></span></code></pre></div><p>每一轮，客户端都要把<strong>从头到尾的全部历史</strong>重新发送一遍。对话滚到几万 token 后，每次请求携带的内容都非常大（《<a href="/ai-handbook/tips/token-efficiency">效率与省钱技巧</a>》里说的&quot;输入也在花钱&quot;就是这个道理）。</p><p>更麻烦的是，模型收到这些内容后，要把每一部分<strong>从头计算一遍</strong>才能开始回答。这部分计算叫&quot;预填充&quot;（Prefill），它发生在你看到第一个字之前——内容越多，等待越久。</p><h2 id="_2-缓存-算过的部分别再算一遍" tabindex="-1">2. 缓存：算过的部分别再算一遍 <a class="header-anchor" href="#_2-缓存-算过的部分别再算一遍" aria-label="Permalink to &quot;2. 缓存：算过的部分别再算一遍&quot;">​</a></h2><p>模型处理文本时，会为每个 token 生成一份中间计算结果（技术上的名字叫 KV 状态），后面的 token 都要用到前面 token 的这些结果。</p><p><strong>上下文缓存（Context Cache，也叫 Prompt Cache）做的事</strong>：服务端把这些中间结果存下来。下次请求进来时，先比对新内容的开头部分——如果和上次请求的开头<strong>一字不差</strong>，这部分直接复用上次的结果，跳过重复计算。</p><p>回到第 1 节的例子：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>第 2 轮请求：[系统提示词 + 问题 1 + 回答 1] ← 这段和上一轮完全相同，命中缓存</span></span>
<span class="line"><span>             [问题 2]                       ← 只有新增部分需要真正计算</span></span></code></pre></div><p>对话越长，开头相同的部分越大，缓存省掉的重复计算就越多。Claude Code、Codex CLI 这类编程工具之所以把系统提示词和工具定义固定放在对话最前面，并且每一轮都保持不变，正是为了让这个最大的&quot;公共开头&quot;能被缓存。</p><h2 id="_3-对话的实际影响-更快、更便宜" tabindex="-1">3. 对话的实际影响：更快、更便宜 <a class="header-anchor" href="#_3-对话的实际影响-更快、更便宜" aria-label="Permalink to &quot;3. 对话的实际影响：更快、更便宜&quot;">​</a></h2><h3 id="_3-1-更便宜" tabindex="-1">3.1 更便宜 <a class="header-anchor" href="#_3-1-更便宜" aria-label="Permalink to &quot;3.1 更便宜&quot;">​</a></h3><p>缓存命中的部分按大幅折扣计费，不按正常输入价收。以主流 API 为参考：</p><table tabindex="0"><thead><tr><th>部分</th><th>计费方式</th></tr></thead><tbody><tr><td>命中缓存的输入</td><td>约为正常输入价的 1/10 ~ 1/2（各平台不同）</td></tr><tr><td>未命中的输入</td><td>正常输入价</td></tr><tr><td>输出</td><td>不受缓存影响</td></tr></tbody></table><p>在第三方中转平台（如 STJAPI）上，用量明细里的&quot;缓存读取&quot;通常也是单独一列、单价明显更低。长会话中，命中缓存的部分往往占每次请求输入的绝大部分，实际费用可能只有&quot;全部按原价算&quot;的几分之一。</p><h3 id="_3-2-更快" tabindex="-1">3.2 更快 <a class="header-anchor" href="#_3-2-更快" aria-label="Permalink to &quot;3.2 更快&quot;">​</a></h3><p>缓存跳过的是&quot;预填充&quot;计算——也就是你等第一个字出现的那段时间。会话越长、命中率越高，首字响应越明显地变快。</p><h3 id="_3-3-对话质量没有影响" tabindex="-1">3.3 对话质量没有影响 <a class="header-anchor" href="#_3-3-对话质量没有影响" aria-label="Permalink to &quot;3.3 对话质量没有影响&quot;">​</a></h3><p>缓存复用的只是中间计算结果，结果和现算一模一样。命中缓存不会让回答变差，也和上下文窗口大小无关——它影响的是速度和费用，不是模型的&quot;记忆容量&quot;。</p><h2 id="_4-什么情况下缓存会失效" tabindex="-1">4. 什么情况下缓存会失效 <a class="header-anchor" href="#_4-什么情况下缓存会失效" aria-label="Permalink to &quot;4. 什么情况下缓存会失效&quot;">​</a></h2><p>缓存命中的条件非常严格：<strong>从第一个 token 开始的前缀必须完全一致</strong>。常见的不命中原因：</p><table tabindex="0"><thead><tr><th>场景</th><th>结果</th></tr></thead><tbody><tr><td>系统提示词里写了当前时间、随机 ID 等动态内容</td><td>开头就变了，后面全部缓存作废</td></tr><tr><td>客户端修改了系统提示词或工具定义（如升级版本后）</td><td>从变化处开始缓存失效</td></tr><tr><td>距离上次对话超过几分钟（缓存有过期时间）</td><td>缓存被清除，下一轮全价</td></tr><tr><td>切换了模型</td><td>不同模型不共享缓存</td></tr></tbody></table><p>其中过期时间（TTL）值得注意：主流平台的缓存一般只保留几分钟到一小时不等。这也是&quot;中途停下来吃个饭，回来继续聊第一句会明显变慢变贵&quot;的原因。</p><h2 id="_5-怎么让对话尽量命中缓存" tabindex="-1">5. 怎么让对话尽量命中缓存 <a class="header-anchor" href="#_5-怎么让对话尽量命中缓存" aria-label="Permalink to &quot;5. 怎么让对话尽量命中缓存&quot;">​</a></h2><p>不需要手动操作任何东西——缓存由客户端和服务端自动完成。你能做的是不破坏它：</p><ol><li><strong>保持前缀稳定</strong>。如果是自己写程序调 API，把固定内容（系统提示词、工具定义、文档）放最前面，把每次变化的内容（用户消息、时间戳）放最后。</li><li><strong>同一个会话里连续对话</strong>。隔几分钟就断开重聊，等于每次都重新付全价预填充。</li><li><strong>别频繁切换模型</strong>。同一个任务尽量用同一个模型跑完，切换即缓存作废。</li><li><strong>长会话主动压缩</strong>。用 <code>/compact</code> 压缩历史（见《<a href="/ai-handbook/tips/token-efficiency">效率与省钱技巧</a>》），压缩后前缀变短，但后续轮次又能稳定命中了。</li></ol><h2 id="_6-一页速查" tabindex="-1">6. 一页速查 <a class="header-anchor" href="#_6-一页速查" aria-label="Permalink to &quot;6. 一页速查&quot;">​</a></h2><ul><li>模型无状态，每轮对话都重发全部历史并重新计算——缓存就是&quot;算过的开头别重算&quot;。</li><li>命中条件：从第一个 token 起完全一致的前缀；命中部分按 1/10 ~ 1/2 的价格计费，且首字响应更快。</li><li>缓存几分钟不用就过期；开头有动态内容（时间戳等）会从那里开始全部作废。</li><li>缓存不影响回答质量，也不增加记忆容量，只影响速度和费用。</li><li>实践上：连续对话、不频繁切模型、长会话主动压缩，就是在&quot;喂&quot;缓存。</li></ul>`,32)])])}const q=a(s,[["render",r]]);export{u as __pageData,q as default};
